body:
{
  "pains": [
    {
      "id": "pain:verified-list-bounces",
      "statement": "We paid for the contact data, loaded the list, and most of the emails bounced.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "The bounce report on the first send of a sequence built from a purchased list comes back with most addresses undeliverable.",
        "operational": "They chase the vendor for a refund, then buy or verify the same contacts again somewhere else before they can send.",
        "personal": null,
        "personal_note": "No source shows the personal cost. The Trustpilot reviews stop at the bounce rate and the refused refund. Searched Trustpilot 1-3 star reviews for Apollo, ZoomInfo and Seamless.AI. G2, Capterra, TrustRadius and Reddit refused the fetch."
      },
      "workflow": "The first send of an email sequence built from a list exported out of ZoomInfo or Apollo, at the step where the bounce report comes back and the deliverability numbers show the list was stale.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "An Apollo buyer posted on Trustpilot on 28 Sep 2026 that well over 65% of sends bounced or failed and the refund was refused.",
        "cites": ["src:1"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "Well over 65% bounce and failed rate.", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "Most emails were non deliverable.", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "Outdated and inaccurate!", "cites": ["src:3"] }
          ],
          "costs_them": "The subscription money, plus a send that went nowhere and a vendor that will not refund it.",
          "fears": "No source shows the fear directly. The quotes stop at the bounce rate and the refused refund.",
          "dream_outcome": "A list they can send to on day one without most of it bouncing."
        }
      },
      "relief": {
        "line": "Sends that land. The list they export is the list they can email.",
        "says": [
          { "role": "economic_buyer", "verbatim": "Lusha seems to have the most updated and reliable contact information.", "cites": ["src:16"] }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Data they trust without checking. Not found yet.",
        "says": [],
        "gap": "Read the 4 and 5 star Trustpilot reviews for Apollo and Lusha. They describe relief (reliable data, time saved). None describes a change in standing a year later."
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment across providers goes after this pain. Apollo's own Trustpilot carries the same complaint (src:1), so Apollo cannot claim it is solved.",
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:numbers-that-dont-connect",
      "statement": "We get a number back for almost everyone, but when the SDRs dial only about a quarter reach the right person.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Coverage looks near-complete, but dial outcomes show wrong people, dead lines and old numbers.",
        "operational": "They layer in another phone provider, sample each waterfall step and log dial outcomes per source to find where the bad numbers come from.",
        "personal": null,
        "personal_note": "No source shows what this costs the person running the waterfall or the SDRs dialing. The Clay thread asks for a reality check and stops at the numbers."
      },
      "workflow": "A Clay phone enrichment waterfall for mobile and direct dials feeding SDR call lists, at the step where SDRs dial and the connect rate shows only about 25% of returned numbers are correct.",
      "type": "felt",
      "confidence": "medium",
      "priority": 2,
      "felt_evidence": {
        "kind": "paying",
        "what": "The team added another major phone provider to its waterfall to lift reachable numbers from about 25% to the mid 30s.",
        "cites": ["src:5"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "When our SDRs actually dial, only about a quarter of those numbers turn out to be correct and reachable.", "cites": ["src:5"] },
            { "situation": "when_looking", "verbatim": "I just want a reality check on whether ~25% is normal or whether we're the outlier.", "cites": ["src:5"] }
          ],
          "costs_them": "Extra provider spend and their own time auditing each step, for a connect rate still in the mid 30s.",
          "fears": "That their setup is the outlier and the stack they own is the reason SDRs cannot connect.",
          "dream_outcome": "A number on a contact that means the SDR reaches that person when they dial."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Wrong email and phone number.", "cites": ["src:3"] }
          ],
          "costs_them": "Dials spent on numbers that do not reach the contact.",
          "fears": "No source shows the fear. The quote stops at the wrong number.",
          "dream_outcome": "Call lists where the number on the record is the person's real number."
        }
      },
      "relief": {
        "line": "Fewer dials, same meetings. The numbers reach the person on the record.",
        "says": [
          { "role": "end_user", "verbatim": "They would need to make 175 calls to my 100 to get even a half of my meetings.", "cites": ["src:17"] }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "The rep everyone else is chasing. Not found yet.",
        "says": [],
        "gap": "Read the 5 star Lusha Trustpilot reviews. One invited review describes fewer dials per meeting (relief). None describes a lasting change in standing."
      },
      "segments": ["seg:midmarket", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment covers the provider layering. The parallel dialer (feat:dialer) speeds up dialing but does not fix bad numbers. The Clay thread's real ask is verified accuracy per provider, not coverage.",
      "cites": ["src:5", "src:3"]
    },
    {
      "id": "pain:locked-into-the-year",
      "statement": "We signed up, the data did not work, and now they will not let us out of a 12-month contract.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Cancellation requests get refused, renewals arrive automatically, and unpaid months go to collections.",
        "operational": "They book sales calls just to cancel, put renewal notice dates in writing, offer buyouts and dispute charges.",
        "personal": null,
        "personal_note": "No source shows the personal cost beyond the money. The reviews describe refusals and collections, not what it did to the buyer's standing or week."
      },
      "workflow": "The renewal and cancellation step of an annual data contract with ZoomInfo, Seamless.AI or Apollo: emailing support to cancel, being told to book a sales call, and the 60-day notice window before the auto-renewal.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "switching",
        "what": "A Seamless.AI buyer is declining another year and asking in writing for auto-renewal to be turned off (Trustpilot, 1 Oct 2026).",
        "cites": ["src:12"]
      },
      "revealed_by": null,
      "triggers": [
        { "event": "The renewal notice window opens: a 60-day notice period before an automatic 12-month renewal.", "cites": ["src:11"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Didn't realize it was a year contract.", "cites": ["src:8"] },
            { "situation": "venting", "verbatim": "They lock you in for 12 months with no break clause and send you to collections.", "cites": ["src:10"] },
            { "situation": "when_refusing", "verbatim": "Declining another year of Seamless.AI shouldn’t require an appointment.", "cites": ["src:12"] },
            { "situation": "when_it_bites", "verbatim": "Instead, we received emails referencing collections for a subscription nobody in our company was using.", "cites": ["src:22"] },
            { "situation": "venting", "verbatim": "Unhelpful service because their commission check depends on you not cancelling.", "cites": ["src:9"] }
          ],
          "costs_them": "A year of fees for data nobody uses, plus collections notices.",
          "fears": "Getting auto-renewed for another year, or sent to collections, over a tool they already stopped using.",
          "dream_outcome": "Pay monthly and leave the month the data stops working."
        }
      },
      "relief": {
        "line": "Month to month. They pay for the data while it works and leave when it stops.",
        "says": [],
        "gap": "Searched the 4 and 5 star Trustpilot reviews for Apollo and Lusha. None mentions contract terms as a relief."
      },
      "euphoria": {
        "line": "Vendor on probation. Not found yet.",
        "says": [],
        "gap": "No after-state quote about contract flexibility found in any review read."
      },
      "segments": ["seg:smb"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers this. Month-to-month billing with self-serve cancellation would. Apollo's own Trustpilot carries a collections complaint (src:22), so Apollo cannot claim it is solved.",
      "cites": ["src:8", "src:10", "src:22"]
    },
    {
      "id": "pain:paying-twice-for-one-contact",
      "statement": "Every email costs a credit, the credits don't roll over, and when the data is wrong we buy the same contact again somewhere else.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "The monthly credit bill climbs while unused credits expire at month end.",
        "operational": "They buy the missing or wrong contacts from a second vendor, or ration credits to avoid upgrading, especially outside the US.",
        "personal": null,
        "personal_note": "No source shows the personal cost. The reviews stop at the price."
      },
      "workflow": "Revealing emails one credit at a time in Apollo or ZoomInfo on a monthly plan, at the point where wrong or missing contacts get bought again from another provider.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "paying",
        "what": "A ZoomInfo buyer bought the same contact information again from another provider after the ZoomInfo data failed.",
        "cites": ["src:4"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "They charge you $99 for a thousand credits a month, 1 email is 1 credit.", "cites": ["src:6"] },
            { "situation": "venting", "verbatim": "The credits don't roll over and they are expensive as hell.", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "I ended up having to purchase the same information elsewhere.", "cites": ["src:4"] },
            { "situation": "venting", "verbatim": "If you plan to go international please review cost of your plan.", "cites": ["src:7"] }
          ],
          "costs_them": "A per-contact bill that resets every month, plus a second vendor's bill for the same contacts.",
          "fears": "No source shows the fear. The quotes stop at the cost.",
          "dream_outcome": "Pay once for a contact that works."
        }
      },
      "relief": {
        "line": "One bill, one contact. What they pay for is what they can use.",
        "says": [],
        "gap": "Read the 4 and 5 star Apollo Trustpilot reviews. The ones about price still call it expensive (src:7). None describes the cost going away."
      },
      "euphoria": {
        "line": "Data that pays for itself. Not found yet.",
        "says": [],
        "gap": "No after-state quote about cost found in any review read."
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment can stand in for buying a second database. It does not fix credits expiring or the per-contact price, which buyers name as the pain.",
      "cites": ["src:6", "src:4"]
    },
    {
      "id": "pain:nobody-real-answers",
      "statement": "Once the contract is signed you cannot get a real person to fix anything.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Support tickets bounce between agents, and nobody owns the fix.",
        "operational": "They repeat the same question to several agents, escalate through sales, and post public reviews to get an answer.",
        "personal": null,
        "personal_note": "No source shows the personal cost. The reviews describe the loop, not its effect on the person."
      },
      "workflow": "The vendor support channel for Apollo or ZoomInfo after purchase: raising a data or sending-limit issue and being passed between support agents.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "An Apollo buyer posted on Trustpilot on 29 Sep 2026 about five support agents repeating the same question.",
        "cites": ["src:13"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "The same question, repeated endlessly.", "cites": ["src:13"] },
            { "situation": "venting", "verbatim": "You can never reach anyone for help and they don't let you cancel!", "cites": ["src:14"] },
            { "situation": "when_it_bites", "verbatim": "Wrong platform issued and no customer support once contract was signed.", "cites": ["src:15"] },
            { "situation": "when_it_bites", "verbatim": "After i paid $3,200 the support team told me i cannot send one email for 90 days.", "cites": ["src:24"] }
          ],
          "costs_them": "Paid seats sitting idle while they wait on support. In one case $3,200 paid with no sending for 90 days.",
          "fears": "Having paid up front for something that cannot be used and nobody will fix.",
          "dream_outcome": "One person who owns the problem and fixes it."
        }
      },
      "relief": {
        "line": "One answer. Asked once, fixed once.",
        "says": [],
        "gap": "The 4 and 5 star Apollo reviews read mention onboarding and a learning curve, not support resolving an issue."
      },
      "euphoria": {
        "line": "A vendor that feels like part of the team. Not found yet.",
        "says": [],
        "gap": "No after-state quote about support found in any review read."
      },
      "segments": ["seg:smb"],
      "feature_ref": null,
      "feature_note": "No product feature covers this. Responsive human support would. Apollo's own Trustpilot carries the complaint (src:13, src:24).",
      "cites": ["src:13", "src:14", "src:15"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers compare named databases and layer providers on top of each other, so they know solutions exist and are choosing between them.",
      "cites": ["src:19", "src:5"]
    }
  },
  "stats": [],
  "keywords": [
    "apollo bounce rate",
    "zoominfo cancel contract",
    "zoominfo auto renewal",
    "seamless.ai cancel subscription",
    "phone number accuracy waterfall",
    "credits don't roll over",
    "contact data outdated wrong phone number"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "Which of these five did your last ten new customers name on the first call: bounces, phone numbers that don't connect, contract lock-in, credit cost, or support?",
      "why": "The ranking comes from public complaints mostly about competitors. Customer words would confirm or reorder it.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-personal-rung",
      "question": "When a bad list bounces or a call list doesn't connect, what happens to the person who bought or ran it: their manager, their quota, their domain?",
      "why": "Every personal rung is null. No public source showed the personal cost.",
      "would_change": "pains[].shape.personal"
    },
    {
      "id": "q:pains-revops-duplicates",
      "question": "Do RevOps buyers tell you Apollo-to-CRM syncs create duplicate or mismatched accounts, and is that why they hire for data hygiene?",
      "why": "Two job postings (src:20, src:21) pay salaries for duplicate and missing-record cleanup, but no buyer-voice complaint could be read: the HubSpot Community thread and Reddit refused the fetch. So seg:revops has no pain row of its own.",
      "would_change": "pains[] (a new RevOps pain), pains[].segments"
    },
    {
      "id": "q:pains-own-reviews",
      "question": "Apollo's own Trustpilot carries bounce, collections and support complaints. Which do churned customers name when they leave?",
      "why": "Three of the five pains show up against Apollo itself, which limits what positioning can claim.",
      "would_change": "pains[].feature_note, pains[].confidence"
    },
    {
      "id": "q:pains-harness",
      "question": "What problem do customers say GTM Harness solves for them, in their words?",
      "why": "No buyer quote in this sweep pointed at AI research or outreach agents. A 5 star review praises time saved over manual prospect research (src:18), but no buyer complained about the manual work.",
      "would_change": "pains[] (a latent pain revealed_by feat:harness)"
    }
  ],
  "sources": [
    { "id": "src:1", "url": "https://www.trustpilot.com/review/apollo.io?stars=1&stars=2&stars=3", "title": "Trustpilot review of Apollo.io by Michael (AU)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-09-28", "pulled": "2026-10-12", "verbatim": "Well over 65% bounce and failed rate. […] No help resolving anything and refused refund." },
    { "id": "src:2", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Frank Scotti (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-09-14", "pulled": "2026-10-12", "verbatim": "Most emails were non deliverable. […] When requesting cancellation, the company reps are completely unwilling to cancel." },
    { "id": "src:3", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Stephan Francis", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-03-15", "pulled": "2026-10-12", "verbatim": "Outdated and inaccurate! […] Wrong email and phone number." },
    { "id": "src:4", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Sean R.", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-03-14", "pulled": "2026-10-12", "verbatim": "Not happy at all with the contact data I got from ZoomInfo. […] I ended up having to purchase the same information elsewhere." },
    { "id": "src:5", "url": "https://community.clay.com/x/general/msg_OejZIEJFTuIO/phone-number-accuracy-challenges-and-best-practice", "title": "Phone number accuracy challenges and best practices for outbound B2B dialing waterfalls (m.m)", "venue": "Clay community, hosted by Clay (an enrichment vendor); poster is a user running a waterfall", "speaker": "practitioner", "published": "2026-09-16", "pulled": "2026-10-12", "verbatim": "mobile and direct dials, B2B, fairly niche security/compliance titles […] Coverage looks great on paper: we get a number back for roughly 9 out of 10 contacts. […] When our SDRs actually dial, only about a quarter of those numbers turn out to be correct and reachable. […] We tested layering in another major provider and it moves us into the mid 30s. […] I just want a reality check on whether ~25% is normal or whether we're the outlier." },
    { "id": "src:6", "url": "https://www.trustpilot.com/review/apollo.io?stars=1&stars=2&stars=3", "title": "Trustpilot review of Apollo.io by Thymen Van Volsem (BE)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-10-02", "pulled": "2026-10-12", "verbatim": "They charge you $99 for a thousand credits a month, 1 email is 1 credit. […] The credits don't roll over and they are expensive as hell." },
    { "id": "src:7", "url": "https://www.trustpilot.com/review/apollo.io?stars=1&stars=2&stars=3", "title": "Trustpilot review of Apollo.io by Amirul (MY)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-09-18", "pulled": "2026-10-12", "verbatim": "If you plan to go international please review cost of your plan. […] It quite expensive for us to upgraded better plan." },
    { "id": "src:8", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by an anonymous user (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-07-14", "pulled": "2026-10-12", "verbatim": "Didn't realize it was a year contract. […] Tried cancelling immediately and they charged me two more times after first started reaching out" },
    { "id": "src:9", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Jeff Gunn (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-08-24", "pulled": "2026-10-12", "verbatim": "Terrible service, extremely difficult to cancel contracts. […] Unhelpful service because their commission check depends on you not cancelling." },
    { "id": "src:10", "url": "https://www.trustpilot.com/review/seamless.ai?stars=1&stars=2", "title": "Trustpilot review of Seamless.AI by Ryan Unrau (MX)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-10-06", "pulled": "2026-10-12", "verbatim": "They lock you in for 12 months with no break clause and send you to collections. […] Offered even half up front as a buy out." },
    { "id": "src:11", "url": "https://www.trustpilot.com/review/seamless.ai?stars=1&stars=2", "title": "Trustpilot review of Seamless.AI by Jeffrey Beane (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-07-01", "pulled": "2026-10-12", "verbatim": "They are claiming a mandatory 60-day notice period and are attempting to force an automatic 12-month renewal. […] Prospective customers should be extremely wary of these restrictive contract terms." },
    { "id": "src:12", "url": "https://www.trustpilot.com/review/seamless.ai?stars=1&stars=2", "title": "Trustpilot review of Seamless.AI by Yakir Biegeleisen (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-10-01", "pulled": "2026-10-12", "verbatim": "Declining another year of Seamless.AI shouldn’t require an appointment. […] I’m simply asking them to disable auto-renewal and confirm it in writing." },
    { "id": "src:13", "url": "https://www.trustpilot.com/review/apollo.io?stars=1&stars=2&stars=3", "title": "Trustpilot review of Apollo.io by RC (GB)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-09-29", "pulled": "2026-10-12", "verbatim": "Five support agents. […] The same question, repeated endlessly." },
    { "id": "src:14", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Kalib Winters (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-06-22", "pulled": "2026-10-12", "verbatim": "You can never reach anyone for help and they don't let you cancel!" },
    { "id": "src:15", "url": "https://www.trustpilot.com/review/zoominfo.com?stars=1&stars=2", "title": "Trustpilot review of ZoomInfo by Joe (US)", "venue": "Trustpilot, independent review site", "speaker": "buyer", "published": "2026-09-21", "pulled": "2026-10-12", "verbatim": "Wrong platform issued and no customer support once contract was signed." },
    { "id": "src:16", "url": "https://www.trustpilot.com/review/lusha.com?stars=5", "title": "Trustpilot review of Lusha by megan (US)", "venue": "Trustpilot, independent review site; verified review", "speaker": "buyer", "published": "2022-09-05", "pulled": "2026-10-12", "verbatim": "Lusha seems to have the most updated and reliable contact information. […] Easy download into CSV for easy upload into our CRM." },
    { "id": "src:17", "url": "https://www.trustpilot.com/review/lusha.com?stars=5", "title": "Trustpilot review of Lusha by Carol (CA)", "venue": "Trustpilot; review invited by Lusha, which may bias it", "speaker": "buyer", "published": "2025-07-28", "pulled": "2026-10-12", "verbatim": "They would need to make 175 calls to my 100 to get even a half of my meetings. […] It reduces your sales cycle length by approximately 40%." },
